const courseData=[{id:1,name:'SQL Fundamentals',skill:'SQL',desc:'Start with SELECT, WHERE and sorting. Build a solid foundation for working with relational data.',level:'Beginner',hours:4,type:'Guided lesson',prereq:null},{id:2,name:'Advanced SQL & Practice',skill:'SQL',desc:'Join multiple tables, aggregate results, and use window functions to answer business questions.',level:'Intermediate',hours:6,type:'Practice lab',prereq:1},{id:3,name:'Customer Insights Project',skill:'SQL',desc:'Use a synthetic retail dataset to investigate purchases and deliver five actionable insights.',level:'Applied',hours:5,type:'Portfolio project',prereq:2},{id:4,name:'Power BI Essentials',skill:'Power BI',desc:'Connect your data, build a simple model, and create your first interactive report.',level:'Beginner',hours:4,type:'Guided lesson',prereq:null},{id:5,name:'Build a Business Dashboard',skill:'Power BI',desc:'Design a business dashboard with clear measures and useful visualizations.',level:'Applied',hours:6,type:'Portfolio project',prereq:4},{id:6,name:'Statistics for Decisions',skill:'Statistics',desc:'Understand averages, spread, sampling, and the difference between correlation and causation.',level:'Beginner',hours:3,type:'Guided lesson',prereq:null},{id:7,name:'GIS Foundations',skill:'GIS',desc:'Explore spatial data, map projections, and a simple environmental mapping exercise.',level:'Beginner',hours:4,type:'Guided lesson',prereq:null}];
const navs={Student:[['Dashboard','dashboard'],['My Profile','user'],['Assessment','assessment'],['My Skills','skills'],['Skill Gaps','gap'],['Career Roles','role'],['Learning Path','learning'],['Internships','internship'],['Jobs','role'],['Applications','application'],['Portfolio','portfolio'],['Mentorship','mentorship']],Industry:[['Dashboard','dashboard'],['Company Profile','building'],['Opportunities','internship'],['Candidates','mentorship'],['Applications','application'],['Analytics','gap']],Institution:[['Dashboard','dashboard'],['Students','mentorship'],['Skill Analytics','gap'],['Placement Progress','application'],['Industry Demand','trend']],Academician:[['Dashboard','dashboard'],['Mentorship','mentorship'],['Collaboration','building']]};
function ready(req=roles[selectedRole]){return Math.round(Object.entries(req).reduce((a,[k,v])=>a+Math.min((S.skills[k]||0)/v,1),0)/Object.keys(req).length*100)}
function gap(k,v){return Math.max(0,v-(S.skills[k]||0))}function gapLabel(n){return n===0?'No gap':n<=10?'Low gap':n<=20?'Medium gap':'High gap'}
function match(o){let skill=ready(o.requirements),interest=S.profile.interest===o.category?100:40,eligible=o.education.includes(S.profile.degree),experience=Math.min(100,S.projects.filter(p=>p.skills.some(k=>k in o.requirements)).length*50),loc=o.location==='Remote'||o.location.toLowerCase()===S.profile.location.toLowerCase()?100:0;return {skill,interest,eligible,experience,loc,total:Math.round(skill*.5+interest*.2+(eligible?100:0)*.15+experience*.1+loc*.05)}}
function ranked(type){return S.opportunities.filter(o=>(!type||o.type===type)&&match(o).eligible).sort((a,b)=>match(b).total-match(a).total)}
async function save(patch){if(standalone){try{localStorage.setItem(standaloneStorageKey,JSON.stringify({...S,...patch}))}catch{throw Error('Could not save changes in this browser. Check that local storage is available.')}Object.assign(S,patch);return}const r=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(patch)});if(!r.ok)throw Error('Could not save changes. Please try again.');Object.assign(S,patch)}
function toast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),3500)}
function go(p){page=p;filter='All';search='';render();window.scrollTo(0,0)}
function switchPortal(p){portal=p;go('Dashboard')}
function btn(text,action,primary=false,icon='arrow'){return `<button class="btn ${primary?'primary':''}" onclick="${action}">${text}${icon?I(icon):''}</button>`}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="heading-buttons">${actions}</div></div>`}
function head(title,sub='',action=''){return `<div class="card-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function link(text,p){return `<button class="text-link" onclick="go('${p}')">${text} ${I('arrow')}</button>`}
function pill(t,c='gray'){return `<span class="pill ${c}">${t}</span>`}
function stat(label,value,note,icon,color='peach'){return `<div class="stat-card"><div class="stat-top">${label}<span class="square ${color}">${I(icon)}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function notice(text){return `<div class="notice">${I('info')}<span>${text}</span></div>`}
function empty(title,text,action=''){return `<div class="card empty">${I('application')}<h3>${title}</h3><p>${text}</p>${action}</div>`}
function render(){document.title=`${page} · Kaizen Connect`;document.getElementById('app').innerHTML=`<aside class="sidebar" id="sidebar"><a href="#" class="brand" onclick="go('Dashboard');return false"><div class="brand-mark">k</div><div><div class="brand-name">kaizen<span> connect</span></div><small>FROM SKILLS TO OPPORTUNITIES</small></div></a><div class="workspace"><div class="square">${I(portal==='Student'?'learning':'building')}</div><div><select aria-label="Switch demo portal" onchange="switchPortal(this.value)">${Object.keys(navs).map(p=>`<option ${p===portal?'selected':''}>${p}</option>`).join('')}</select><small style="display:block;padding-left:4px">${portal==='Student'?'Your career workspace':'Demo workspace'}</small></div>${I('down')}</div><div class="navigation"><div class="nav-label">WORKSPACE</div>${navs[portal].map(([n,i],idx)=>`${idx===7?'<div class="nav-divider"></div><div class="nav-label">OPPORTUNITIES</div>':''}<button class="nav-item ${page===n?'active':''}" onclick="go('${n}')">${I(i)}${n}${n==='Internships'?`<span class="nav-badge">${ranked('Internship').length}</span>`:''}${n==='Applications'&&S.applications.length?`<span class="nav-badge">${S.applications.length}</span>`:''}</button>`).join('')}</div><div class="sidebar-foot"><div class="help-card"><strong>${I('spark')} A little guidance, a big step.</strong><p>Your next opportunity begins with knowing your strengths.</p><button onclick="guide()">Explore how Kaizen works ${I('arrow')}</button></div><small>SIH26044 · Made for your next chapter</small></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" aria-label="Open menu" onclick="document.getElementById('sidebar').classList.toggle('open')">${I('menu')}</button><span>${portal} Portal</span>${I('chevron')}<b>${page}</b></div><div class="top-right"><span class="demo-pill"><i></i> DEMO WORKSPACE</span><button class="icon-button notification" aria-label="Notifications" onclick="notifications()">${I('bell')}</button><div class="divider-v"></div><button class="user-chip" onclick="${portal==='Student'?"go('My Profile')":"demoInfo()"}"><div class="avatar">${portal==='Student'?'AS':portal==='Industry'?'LL':portal==='Institution'?'PI':'DR'}</div><div><strong>${portal==='Student'?esc(S.profile.name):portal==='Industry'?'Lumina Labs':portal==='Institution'?'Placement Office':'Dr. Meera Rao'}</strong><small>${portal==='Student'?'Student · Year '+esc(S.profile.year):portal+' workspace'}</small></div>${I('down')}</button></div></header><main class="page">${content()}<footer class="page-footer"><span>© 2026 Kaizen Connect. Built for possibilities.</span><span>${I('shield')} Synthetic data · Explainable by design</span></footer></main></div>`}
function content(){if(portal==='Industry')return industry();if(portal==='Institution')return institution();if(portal==='Academician')return academician();switch(page){case'Dashboard':return dashboard();case'My Profile':return profile();case'Assessment':return assessment();case'My Skills':return skillsPage();case'Skill Gaps':return gapsPage();case'Career Roles':return rolesPage();case'Learning Path':return learningPage();case'Internships':case'Jobs':return opportunitiesPage();case'Applications':return applicationsPage();case'Portfolio':return portfolioPage();case'Mentorship':return mentorship();default:return dashboard()}}
function skillBars(){return Object.entries(roles[selectedRole]).map(([k,v])=>`<div class="skill-row"><span class="skill-name">${k}</span><div class="bar-track"><div class="bar-fill ${gap(k,v)===0?'strong':''}" style="width:${S.skills[k]||0}%"></div><i class="target-mark" style="left:${v}%"></i></div><span class="skill-value">${S.skills[k]||0}%</span>${pill(gapLabel(gap(k,v)),gap(k,v)===0?'green':gap(k,v)>20?'red':'orange')}</div>`).join('')}
function ring(n){return `<div class="ring"><svg viewBox="0 0 140 140"><circle cx="70" cy="70" r="59" fill="none" stroke="#f4f1ee" stroke-width="9"/><circle cx="70" cy="70" r="59" fill="none" stroke="#eb8d70" stroke-width="9" stroke-linecap="round" stroke-dasharray="${n*3.707} 370.7"/></svg><div class="ring-label"><strong>${n}<span style="display:inline;font-size:20px;color:#303747">%</span></strong><span>Role readiness</span></div></div>`}
function dashboard(){let r=ready(),best=ranked('Internship');return heading(`Your next chapter starts here, ${esc(S.profile.name.split(' ')[0])} <span style="font-size:23px">✦</span>`,"A clearer picture of your skills. A smarter path to your future.",btn('View my portfolio',"go('Portfolio')",false,'portfolio'))+`<section class="hero"><div><div class="eyebrow">SMALL STEPS. REAL POSSIBILITIES.</div><h2>You have the potential.<br>Let’s build your path to ${esc(selectedRole==='Data Analyst'?'Data Analytics':selectedRole)}.</h2><p>Your skills are the starting point. Discover what comes next.</p>${btn('Explore my skill gaps',"go('Skill Gaps')",true)}</div><div class="hero-visual" aria-hidden="true"><div class="orbit"></div><div class="hero-center">${I('trend')}</div><div class="floating one">${I('checkcircle')} Skills, understood.</div><div class="floating two">${I('target')} Goals, in reach.</div><div class="floating three">${I('spark')} Your future, connected.</div></div></section><div class="stats">${stat('Skills in your profile',Object.keys(S.skills).length+'<span>skills</span>',`${I('checkcircle')} <b>${Object.keys(roles[selectedRole]).length} relevant</b> to your target role`,'skills','peach')}${stat('Career readiness',r+'<span>%</span>',`Towards ${esc(selectedRole)}`,'target','purple')}${stat('Matched internships',best.length.toString().padStart(2,'0'),`${I('trend')} <b>Based on your skills</b>`,'internship','blue')}${stat('Active applications',S.applications.filter(a=>!['Rejected','Withdrawn','Selected'].includes(a.status)).length.toString().padStart(2,'0'),'Your opportunities in motion','application','green')}</div><div class="dashboard-columns"><div><section class="card">${head('Your skills, at a glance',`Where you stand for ${esc(selectedRole)}`,link('View all skills','My Skills'))}<div class="card-body" style="padding-top:0"><div class="skills-legend"><span><i class="dot"></i>Your proficiency</span><span><i class="dot target"></i>Role requirement</span></div>${skillBars()}</div><div class="card-foot">${I('info')} ${S.assessmentTaken?'Includes your latest practice assessment':'Based on seeded assessment scores · Demo data'}</div></section><section class="card">${head('Opportunities that fit you','A good match starts with the skills you already have.',link('View all','Internships'))}${best.slice(0,2).map(opRow).join('')}</section></div><div><section class="card">${head('A little closer to your goal','Your next role, one skill at a time',pill('TARGET ROLE','orange'))}<div class="readiness">${ring(r)}<h3>${esc(selectedRole)}</h3><p>${r>=85?'A strong foundation. Keep practicing your remaining gaps.':`Build on your strengths. Focus on ${Object.entries(roles[selectedRole]).sort((a,b)=>gap(b[0],b[1])-gap(a[0],a[1])).slice(0,2).map(([k])=>k).join(' and ')} to get closer to your goal.`}</p>${btn('See my learning path',"go('Learning Path')",true)}</div><div class="readiness-note">${I('shield')} Rule-based. Transparent. Built around you.</div></section><section class="card">${head('Your next learning steps','Close the gap. Open new doors.')}${nextCourses().map(c=>`<div class="learning-item"><div class="course-icon">${I(c.skill==='SQL'?'code':'gap')}</div><div class="learning-content"><h3>${c.name}</h3><p>${c.skill} · ${c.hours} hours · ${c.level}</p><div class="progress-label"><div class="mini-progress"><i style="width:${S.completed.includes(c.id)?100:0}%"></i></div>${S.completed.includes(c.id)?'Completed':'Not started'}</div></div></div>`).join('')}<div class="learning-cta">${link('View learning roadmap','Learning Path')}</div></section><section class="card journey-card"><h3>${I('learning')} You don’t have to figure it out alone.</h3><p>Find the right guidance from a faculty mentor and take your next step with confidence.</p>${link('Explore mentorship','Mentorship')}</section></div></div>`}
function opRow(o){let m=match(o);return `<div class="opportunity-row"><div class="op-top"><div class="company-logo ${o.color}">${esc(o.initials)}</div><div class="op-title"><h3>${esc(o.title)}</h3><p>${esc(o.company)} <span style="padding:0 4px">·</span> ${esc(o.type)}</p></div>${pill(`${m.total}% match`,'green')}</div><div class="op-meta"><span>${I('location')}${esc(o.location)} · ${esc(o.mode)}</span><span>${I('money')}${esc(o.stipend)}</span></div><div class="op-bottom"><div class="tags">${Object.keys(o.requirements).slice(0,3).map(k=>`<span class="tag">${esc(k)}</span>`).join('')}</div><button class="text-link" onclick="opDetail(${o.id})">View opportunity ${I('arrow')}</button></div></div>`}
function profile(){let p=S.profile;return heading('A profile that’s uniquely you','Bring your background, interests, and ambitions into one place.')+`<div class="two-col"><form class="card full-card" id="profile-form" onsubmit="saveProfile(event)"><h2>Your information</h2><p class="section-subtitle">This structured profile powers eligibility and preference matching.</p><div class="form-grid">${[['name','Full name'],['email','Email address'],['institution','Institution'],['branch','Branch'],['year','Year of study'],['location','Preferred location']].map(([k,l])=>`<div class="field"><label for="p-${k}">${l}</label><input id="p-${k}" name="${k}" value="${esc(p[k])}" ${k==='email'?'type="email"':''} required maxlength="120"></div>`).join('')}<div class="field"><label>Degree</label><select name="degree">${['B.Sc. Data Science','B.Tech','BCA','Other'].map(v=>`<option ${p.degree===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Career interest</label><select name="interest">${['Data & Analytics','Software Development','Design'].map(v=>`<option ${p.interest===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field wide"><label for="bio">About you</label><textarea id="bio" name="bio" maxlength="600">${esc(p.bio)}</textarea></div></div><button class="btn primary" type="submit">Save profile ${I('check')}</button></form><div><div class="card full-card"><div class="profile-banner"></div><div class="avatar profile-avatar">${esc(p.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</div><h2 class="mt">${esc(p.name)}</h2><p>${esc(p.degree)} · Year ${esc(p.year)}<br>${esc(p.institution)}<br>${esc(p.location)}</p>${pill('Student ID · KC-2026-001','orange')}<p>${esc(p.bio)}</p>${btn('Open digital portfolio',"go('Portfolio')",false,'portfolio')}</div>${notice('Demo identity only. Portal switching is not authentication. Do not enter personal, confidential, or real academic records in this shared demo.')}<div class="card full-card"><h2>Your profile, connected</h2><div class="process-path">${['Student data','Assessment','Skill Profile','Role matching'].map(s=>pill(s,'gray')).join(I('arrow'))}</div><p>Education is an eligibility gate. Interests and location influence preference scores. Your assessment and evidence describe your skills.</p></div></div></div>`}
async function saveProfile(e){e.preventDefault();try{await save({profile:{...S.profile,...Object.fromEntries(new FormData(e.target))}});render();toast('Profile saved. Your recommendations have been refreshed.')}catch(e){toast(e.message)}}
const questions=[{skill:'Python',q:'What is the output of len([10, 20, 30])?',options:['2','3','30','An error'],correct:1},{skill:'Python',q:'Which type stores key–value pairs?',options:['List','Tuple','Dictionary','Set'],correct:2},{skill:'SQL',q:'Which clause filters rows before grouping?',options:['ORDER BY','HAVING','WHERE','GROUP BY'],correct:2},{skill:'SQL',q:'Which JOIN keeps every row from the left table?',options:['INNER JOIN','LEFT JOIN','CROSS JOIN','RIGHT JOIN'],correct:1},{skill:'Excel',q:'Which function adds numbers in a range?',options:['COUNT','SUM','FIND','LEFT'],correct:1},{skill:'Excel',q:'What does $A$1 represent?',options:['A text value','A relative reference','An absolute reference','An invalid cell'],correct:2},{skill:'Statistics',q:'Which measure is least affected by an extreme outlier?',options:['Mean','Range','Median','Maximum'],correct:2},{skill:'Statistics',q:'Correlation alone proves that one variable causes another.',options:['True','False'],correct:1},{skill:'Power BI',q:'Which tool is used to transform imported data?',options:['Power Query','Paint','Task Manager','Notepad'],correct:0},{skill:'Power BI',q:'A measure in Power BI commonly uses which language?',options:['HTML','CSS','DAX','Bash'],correct:2}];
function assessment(){return heading('Let your skills speak','A short practice assessment to turn what you know into a structured Skill Profile.',pill('10 QUESTIONS · ABOUT 5 MIN','orange'))+notice('Practice assessment · 2 equally weighted questions per technical skill. Scores are correct answers ÷ 2 × 100. This small demo is not a validated proficiency test; cognitive and professional scores remain seeded. Retaking replaces these five technical scores.')+`<div class="step-line">${['Technical skills','Score calculation','Skill Profile','Skill Gap'].map((s,i)=>`<span class="step ${i===0?'current':''}">${i+1}. ${s}</span>`).join(I('arrow'))}</div><form onsubmit="submitAssessment(event)"><div class="two-col">${questions.map((q,i)=>`<div class="question" style="background:white">${pill(`${String(i+1).padStart(2,'0')} · ${q.skill}`,'orange')}<h3>${q.q}</h3>${q.options.map((a,j)=>`<label class="answer"><input type="radio" name="q${i}" value="${j}" required>${a}</label>`).join('')}</div>`).join('')}</div><div class="card full-card" style="display:flex;align-items:center;justify-content:space-between;gap:15px"><div><strong>Ready to see where you stand?</strong><p>Your answers are scored using a visible, deterministic rubric.</p></div><button class="btn primary" type="submit">Calculate my skills ${I('arrow')}</button></div></form>`}
async function submitAssessment(e){e.preventDefault();let f=new FormData(e.target),scores={};questions.forEach((q,i)=>{scores[q.skill]=(scores[q.skill]||0)+(Number(f.get('q'+i))===q.correct?50:0)});try{await save({skills:{...S.skills,...scores},assessmentTaken:true});go('My Skills');toast('Assessment completed. Your skills and recommendations are updated.')}catch(e){toast(e.message)}}
function skillsPage(){return heading('Your skills, made visible','One explainable profile. The foundation for every recommendation.',btn(S.assessmentTaken?'Retake assessment':'Take assessment',"go('Assessment')",true,'assessment'))+`<div class="stats">${stat('Technical skills','6','Assessment + seeded demo evidence','code')}${stat('Cognitive skills','1','Seeded problem solving score','spark','purple')}${stat('Professional skills','2','Seeded communication & teamwork','mentorship','blue')}${stat('Evidence items',S.projects.length,'Self-reported project evidence','portfolio','green')}</div><div class="card">${head('Skill Profile','Each skill keeps its source and verification status.')}<div class="table-wrap mt"><table><thead><tr><th>Skill</th><th>Category</th><th>Proficiency</th><th>Evidence source</th><th>Verification</th></tr></thead><tbody>${Object.entries(S.skills).map(([k,v])=>`<tr><td><strong>${esc(k)}</strong></td><td>${['Communication','Teamwork'].includes(k)?'Professional':k==='Problem Solving'?'Cognitive':'Technical'}</td><td><div style="display:flex;align-items:center;gap:12px;min-width:130px"><div class="bar-track grow"><div class="bar-fill ${v>=60?'strong':''}" style="width:${v}%"></div></div>${v}%</div></td><td>${S.assessmentTaken&&k in roles['Data Analyst']?'Practice assessment':'Seeded assessment'}</td><td>${pill(S.assessmentTaken&&k in roles['Data Analyst']?'Practice scored':'Demo / not verified',S.assessmentTaken&&k in roles['Data Analyst']?'blue':'gray')}</td></tr>`).join('')}</tbody></table></div><div class="card-foot">${I('info')} Self-reported projects do not automatically increase skill proficiency.</div></div><div class="two-col"><div class="card full-card"><h2>A common skill vocabulary</h2><p>Student Skills, Role Requirements, Courses, and Opportunities all use the same canonical skill names. This makes matching consistent.</p><div class="tags">${Object.keys(S.skills).map(k=>`<span class="tag">${esc(k)}</span>`).join('')}</div></div><div class="card full-card"><h2>Evidence, not just a number</h2><p>Projects, certificates, assessments, internships, and mentor reviews can support a skill. In this MVP, project evidence is self-reported and verification is not automated.</p>${link('View your evidence','Portfolio')}</div></div>`}
function roleSelect(){return `<select class="status-select" aria-label="Target role" onchange="setTargetRole(this.value)">${Object.keys(roles).map(r=>`<option ${r===selectedRole?'selected':''}>${r}</option>`).join('')}</select>`}
function gapsPage(){let req=roles[selectedRole];return heading('Know the gap. Find your next step.','Your current skills, compared with the requirements of your target role.',roleSelect())+`<div class="dashboard-columns"><div><div class="card">${head('Skill Gap Engine',`Target role · ${selectedRole}`,pill('RULE-BASED','orange'))}<div class="table-wrap mt"><table><thead><tr><th>Skill</th><th>Required</th><th>Your level</th><th>Gap</th><th>Priority</th></tr></thead><tbody>${Object.entries(req).map(([k,v])=>`<tr><td><strong>${k}</strong></td><td>${v}%</td><td>${S.skills[k]||0}%</td><td>${gap(k,v)} pts</td><td>${pill(gapLabel(gap(k,v)),gap(k,v)>20?'red':gap(k,v)>0?'orange':'green')}</td></tr>`).join('')}</tbody></table></div></div><div class="card full-card"><h2>Nothing hidden behind the score.</h2><p>Every required skill is equally weighted in this MVP. Higher proficiency in one skill cannot cancel a gap in another.</p><div class="formula">Gap = max(0, required − student)<br>Skill coverage = min(student ÷ required, 1) × 100<br>Readiness = average(required skill coverage)</div><p><b>Worked example · ${Object.keys(req)[0]}</b><br>${Math.min(S.skills[Object.keys(req)[0]]/Object.values(req)[0]*100,100).toFixed(1)}% coverage = min(${S.skills[Object.keys(req)[0]]} ÷ ${Object.values(req)[0]}, 1) × 100.</p><div class="tags">${pill('0 pts: No gap','green')}${pill('1–10: Low gap','orange')}${pill('11–20: Medium gap','orange')}${pill('21+: High gap','red')}</div><p>Readiness is role coverage, not a prediction or guarantee of placement. Learning completion alone never raises a skill score.</p></div></div><div><div class="card">${head('Your role readiness',selectedRole)}<div class="readiness">${ring(ready())}<h3>Your most useful next move</h3><p>Start with the largest gaps, then build project evidence and reassess your skills.</p>${btn('Build my learning path',"go('Learning Path')",true)}</div></div><div class="card full-card"><h2>How the pieces connect</h2><div class="process-path">${['Skill Profile','Target Role','Requirements','Skill Gap','Learning'].map(s=>pill(s,'gray')).join(I('arrow'))}</div><p>Role requirements are curated demo benchmarks, not official hiring standards.</p></div></div></div>`}
function rolesPage(){return heading('A direction worth exploring','Choose a role. Understand its expectations. Make a plan to get there.')+`<div class="three-col">${Object.entries(roles).map(([r,req])=>`<div class="card full-card"><div class="square peach">${I('role')}</div><h2 class="mt">${r}</h2>${pill(`${ready(req)}% skill readiness`,'green')}<p>Benchmark requirements for a ${r.toLowerCase()} learning and career pathway.</p>${Object.entries(req).map(([k,v])=>`<div class="inline-skill"><span>${k}</span><b>${v}%</b></div>`).join('')}<p class="small-text">Demo eligibility: B.Sc. Data Science, B.Tech, or BCA.<br>Preferred: project evidence and communication.</p><button class="btn ${selectedRole===r?'':'primary'}" onclick="setTargetRole('${r}',true)">${selectedRole===r?'View target role':'Set as target role'} ${I('arrow')}</button></div>`).join('')}</div>`}
function learningPage(){let req=roles[selectedRole],courses=courseData.filter(c=>c.skill in req&&gap(c.skill,req[c.skill])>0).sort((a,b)=>gap(b.skill,req[b.skill])-gap(a.skill,req[a.skill])||a.id-b.id);return heading('Small steps. Stronger skills.','A focused roadmap, recommended from your actual skill gaps.',roleSelect())+notice('Curated demo learning content · Completion is a learning milestone, not a proficiency claim. Reassess after practicing to update your Skill Profile.')+`<div class="stats">${stat('Target role readiness',ready()+'<span>%</span>',selectedRole,'target','purple')}${stat('Skills to strengthen',Object.keys(req).filter(k=>gap(k,req[k])>0).length,'Ordered by largest gap','gap')}${stat('Learning milestones',courses.length,'Lessons, practice & projects','learning','blue')}${stat('Completed',S.completed.length,'Across all learning paths','checkcircle','green')}</div>${courses.length?`<div class="three-col">${courses.map((c,i)=>{let done=S.completed.includes(c.id),locked=c.prereq&&!S.completed.includes(c.prereq);return `<div class="card course-card"><div style="display:flex;align-items:center;justify-content:space-between"><span class="course-number">${String(i+1).padStart(2,'0')}</span>${pill(done?'Completed':`${c.skill} · ${gap(c.skill,req[c.skill])} pt gap`,done?'green':'orange')}</div><h3>${c.name}</h3><p>${c.desc}</p><div class="op-meta"><span>${I('clock')}${c.hours} hours</span><span>${I('learning')}${c.level}</span></div>${pill(c.type,'gray')}<button class="btn ${done?'':'primary'}" onclick="courseDetail(${c.id})">${done?'Review lesson':locked?'View prerequisite':'Start learning'} ${I('arrow')}</button></div>`}).join('')}</div>`:empty('You meet every demo benchmark','Keep practicing, build more evidence, or explore another target role.',btn('Explore roles',"go('Career Roles')",true))}`}
function opportunitiesPage(){let type=page==='Jobs'?'Job':'Internship';return heading(type==='Job'?'Find where you belong.':'Your first experience. Your next possibility.',`Skill-driven ${type.toLowerCase()} recommendations, with a reason behind every match.`)+`<div class="filter-bar"><input class="search-input" placeholder="Search roles, companies, skills…" aria-label="Search opportunities" value="${esc(search)}" oninput="search=this.value;renderOpportunityList()"><div class="tabs">${['All','Remote','Hybrid','On-site'].map(t=>`<button class="tab ${filter===t?'active':''}" onclick="filter='${t}';render()">${t}</button>`).join('')}</div><span class="grow"></span><button class="text-link" onclick="matchingInfo()">${I('info')} How matching works</button></div><div id="op-list">${opList(type)}</div>`}
function opList(type){let ops=ranked(type).filter(o=>(filter==='All'||o.mode===filter)&&`${o.title} ${o.company} ${Object.keys(o.requirements).join(' ')}`.toLowerCase().includes(search.toLowerCase()));return ops.length?`<div class="two-col">${ops.map(o=>`<div class="card">${opRow(o)}<div class="card-body" style="padding-top:0"><p class="section-subtitle">${esc(o.description)}</p><div style="display:flex;justify-content:space-between;align-items:center">${pill(o.duration,'gray')}<button class="btn small ${S.applications.some(a=>a.opportunityId===o.id)?'':'primary'}" onclick="opDetail(${o.id})">${S.applications.some(a=>a.opportunityId===o.id)?'View application':'Explore opportunity'} ${I('arrow')}</button></div></div></div>`).join('')}</div>`:empty('No matching opportunities','Try a different search or work arrangement. Eligibility uses your profile’s degree.');}
function renderOpportunityList(){document.getElementById('op-list').innerHTML=opList(page==='Jobs'?'Job':'Internship')}
function applicationsPage(){return heading('Every application. One clear journey.','Stay in the loop, from your first application to your next opportunity.',btn('Find opportunities',"go('Internships')",true,'plus'))+(S.applications.length?`<div class="card">${head('Your applications',`${S.applications.length} opportunity in your journey`)}<div class="table-wrap mt"><table><thead><tr><th>Opportunity</th><th>Applied</th><th>Status</th><th>Next step</th></tr></thead><tbody>${S.applications.map(a=>{let o=S.opportunities.find(o=>o.id===a.opportunityId);return `<tr><td><strong>${esc(o.title)}</strong><div class="small-text">${esc(o.company)}</div></td><td>${a.date}</td><td>${pill(a.status,['Shortlisted','Selected'].includes(a.status)?'green':'orange')}</td><td><button class="text-link" onclick="applicationDetail(${a.id})">View journey ${I('arrow')}</button></td></tr>`}).join('')}</tbody></table></div></div>`:empty('Your next chapter is waiting','Apply to a matched opportunity and track every step here.',btn('Explore internships',"go('Internships')",true)))+`<div class="card full-card"><h2>A clear path, without the guesswork</h2><div class="process-path">${['Submitted','Under Review','Shortlisted','Interview','Selected / Rejected'].map(s=>pill(s,'gray')).join(I('arrow'))}</div><p>Recruiters control hiring decisions. Matching helps explain fit, but never guarantees selection.</p></div>`}
function portfolioPage(){return heading('More than a résumé. Evidence of you.','Your Digital Portfolio is connected directly to your Kaizen profile.',btn('Export portfolio',"exportPortfolio()",false,'download'))+`<div class="dashboard-columns"><div><div class="card full-card"><div class="profile-banner"></div><div class="avatar profile-avatar">AS</div><h2 class="mt">${esc(S.profile.name)}</h2><p>${esc(S.profile.degree)} · ${esc(S.profile.institution)}<br>${esc(S.profile.bio)}</p><div class="tags">${pill(esc(S.profile.location),'gray')}${pill(esc(S.profile.preferredRole),'orange')}${pill('Demo profile','purple')}</div></div><div class="card">${head('Projects','Real context for the skills in your profile.',`<button class="text-link" onclick="addProject()">${I('plus')} Add project</button>`)}<div class="card-body">${S.projects.map(p=>`<div class="activity-item" style="align-items:start"><div class="square blue">${I('code')}</div><div><strong>${esc(p.name)}</strong><p style="line-height:1.8">${esc(p.description)}</p><div class="tags mt">${p.skills.map(k=>`<span class="tag">${esc(k)}</span>`).join('')}</div></div>${pill(p.status,'gray')}</div>`).join('')}</div></div></div><div><div class="card full-card"><h2>Skills & evidence</h2>${Object.entries(S.skills).slice(0,6).map(([k,v])=>`<div class="inline-skill"><span>${k}</span><b>${v}%</b></div>`).join('')}<p class="small-text">${S.assessmentTaken?'Practice assessment':'Synthetic assessment'} · Not independently verified</p></div><div class="card full-card"><h2>Learning milestones</h2>${S.completed.length?S.completed.map(id=>`<div class="activity-item">${I('checkcircle')}<strong>${courseData.find(c=>c.id===id).name}</strong></div>`).join(''):'<p>Your completed learning milestones will appear here.</p>'}<p class="small-text">These are demo completion records, not certifications.</p></div><div class="card full-card"><h2>Verified evidence</h2><p>No independently verified certificates or internship records yet. Mentor verification is a future extension.</p>${pill('Verification pending','gray')}</div></div></div>`}
function mentorship(){return heading('The right guidance makes a difference.','Connect with faculty mentors for direction, feedback, and encouragement.')+notice('Lightweight MVP · Mentorship requests are recorded in this demo. Live scheduling, messaging, and external mentors are future scope.')+`<div class="two-col">${[{id:1,name:'Dr. Meera Rao',area:'Data Analytics & Research',initials:'MR',desc:'Guidance on analytics projects, research questions, and building your first industry-ready portfolio.'},{id:2,name:'Prof. Rohan Desai',area:'Industry Readiness & Communication',initials:'RD',desc:'Practical feedback on project presentations, interview preparation, and your transition to the workplace.'}].map(m=>`<div class="card full-card"><div class="avatar" style="width:48px;height:48px">${m.initials}</div><h2 class="mt">${m.name}</h2>${pill(m.area,'orange')}<p>${m.desc}</p><button class="btn primary" onclick="requestMentor(${m.id})" ${S.mentorshipRequests.includes(m.id)?'disabled':''}>${S.mentorshipRequests.includes(m.id)?'Request recorded':'Request guidance'} ${I('arrow')}</button></div>`).join('')}</div>`}
async function requestMentor(id){try{await save({mentorshipRequests:[...new Set([...S.mentorshipRequests,id])]});render();toast('Guidance request recorded in the demo workspace.')}catch(e){toast(e.message)}}
function modal(title,body){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="icon-button" aria-label="Close dialog" onclick="closeModal()">${I('close')}</button></div><div class="modal-content">${body}</div></section></div>`;document.body.style.overflow='hidden';document.querySelector('.modal .icon-button').focus()}
function closeModal(){document.getElementById('modal-root').innerHTML='';document.body.style.overflow=''}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function opDetail(id){let o=S.opportunities.find(o=>o.id===id),m=match(o),a=S.applications.find(a=>a.opportunityId===id);modal(esc(o.title),`<div class="op-top"><div class="company-logo ${o.color}">${esc(o.initials)}</div><div class="op-title"><h3>${esc(o.company)}</h3><p>${esc(o.location)} · ${esc(o.mode)} · ${esc(o.duration)}</p></div>${pill(`${m.total}% match`,'green')}</div><p>${esc(o.description)}</p>${pill(esc(o.stipend),'orange')}<h3>Why this opportunity?</h3><p>Education: ${m.eligible?'eligible':'not eligible'} · ${esc(S.profile.degree)}.<br>Skills you already meet: ${Object.entries(o.requirements).filter(([k,v])=>gap(k,v)===0).map(([k])=>k).join(', ')||'Work toward the listed benchmarks'}.<br>Build next: ${Object.entries(o.requirements).filter(([k,v])=>gap(k,v)>0).map(([k])=>k).join(', ')||'Maintain your strengths'}.</p><table><thead><tr><th>Skill</th><th>Required</th><th>You</th><th>Gap</th></tr></thead><tbody>${Object.entries(o.requirements).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v}%</td><td>${S.skills[k]||0}%</td><td>${gap(k,v)} pts</td></tr>`).join('')}</tbody></table><h3>Transparent match breakdown</h3><div class="formula">Skills ${m.skill}% × 50% + Interest ${m.interest}% × 20%<br>Education ${m.eligible?100:0}% × 15% + Projects ${m.experience}% × 10%<br>Location ${m.loc}% × 5% = <b>${m.total}% overall match</b></div><p class="small-text">Eligibility is a hard filter. Skills are capped per requirement. Interest uses the selected category; each relevant self-reported project adds 50 experience points (maximum 100). Remote or preferred city earns full location points. No AI scoring.</p><div class="modal-actions">${portal==='Student'?(a?btn('View application',`closeModal();applicationDetail(${a.id})`,true):`<button class="btn primary" ${m.eligible?'':'disabled'} onclick="applyForm(${id})">Apply to this opportunity ${I('arrow')}</button>`):btn('Close','closeModal()')}</div>`)}
function applyForm(id){let o=S.opportunities.find(o=>o.id===id);modal('Make your next move',`<p>Apply for <strong>${esc(o.title)}</strong> at ${esc(o.company)}.</p><form onsubmit="submitApplication(event,${id})"><div class="field"><label for="application-note">A short introduction (optional)</label><textarea id="application-note" name="note" maxlength="1000" placeholder="What excites you about this opportunity?"></textarea></div><label class="answer"><input type="checkbox" required>I consent to sharing my demo profile, skills, and project evidence with this recruiter.</label><p class="small-text">No external application is sent. This is a synthetic opportunity in the demo workspace.</p><div class="modal-actions"><button type="button" class="btn" onclick="opDetail(${id})">Back</button><button class="btn primary" type="submit">Submit application ${I('arrow')}</button></div></form>`)}
async function submitApplication(e,id){e.preventDefault();if(S.applications.some(a=>a.opportunityId===id))return toast('You have already applied.');let date=new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});try{await save({applications:[...S.applications,{id:Date.now(),opportunityId:id,date,status:'Submitted',consent:true,note:new FormData(e.target).get('note'),history:[{status:'Submitted',date}],snapshot:JSON.parse(JSON.stringify({profile:S.profile,skills:S.skills,projects:S.projects}))}]});closeModal();go('Applications');toast('Application submitted. Your next chapter is in motion.')}catch(e){toast(e.message)}}
function applicationDetail(id){let a=S.applications.find(a=>a.id===id),o=S.opportunities.find(o=>o.id===a.opportunityId);modal('Your application journey',`<strong>${esc(o.title)}</strong><p>${esc(o.company)} · Applied ${a.date}</p>${a.history.map((h,i)=>`<div class="activity-item"><div class="square ${i===a.history.length-1?'peach':'green'}">${I('check')}</div><div><strong>${esc(h.status)}</strong><p>${h.date}</p></div></div>`).join('')}<p>Your submitted profile is saved as a snapshot. Future profile edits do not change the application already shared.</p>${!['Withdrawn','Rejected','Selected'].includes(a.status)?`<div class="modal-actions"><button class="btn" onclick="withdraw(${id})">Withdraw application</button></div>`:''}`)}
async function withdraw(id){if(!confirm('Withdraw this application? You cannot resubmit it in this demo.'))return;await changeStatus(id,'Withdrawn');closeModal()}
function courseDetail(id){let c=courseData.find(c=>c.id===id),locked=c.prereq&&!S.completed.includes(c.prereq);const lessons={1:'SELECT retrieves columns from a table. WHERE filters individual rows. ORDER BY sorts the results.\n\nSELECT customer, total FROM orders WHERE total > 500 ORDER BY total DESC;',2:'JOIN combines related tables. GROUP BY produces one summary per group. HAVING filters those grouped results.\n\nSELECT customer_id, SUM(total) FROM orders GROUP BY customer_id HAVING SUM(total) > 1000;',3:'Create a mock orders table with customer_id, date, and total. Write five SQL queries: revenue by month, top customers, average order size, repeat customers, and orders above average. Document your assumptions.',4:'Import a CSV using Get Data. Use Power Query to set types and remove duplicates. Create a bar chart using a category and a numeric measure. Add a slicer, then test that it filters the chart correctly.',5:'Create a small synthetic sales dataset. Define revenue and profit measures. Build an overview with monthly trends and product categories. Add a date slicer and write three observations.',6:'The mean is the sum divided by the count. The median is the middle sorted value. For 2, 3, 4, 5, 100, the mean is 22.8 and the median is 4. The outlier affects the mean more. Correlation alone does not imply causation.',7:'Spatial data connects observations with geographic coordinates. A projection maps the curved Earth onto a plane. Create five fictional observation points and explain why the coordinate reference system matters.'};modal(c.name,`${pill(`${c.skill} · ${c.hours} hours · Demo lesson`,'orange')}<p>${c.desc}</p>${locked?notice(`Complete ${courseData.find(x=>x.id===c.prereq).name} first to unlock this milestone.`):''}<h3>Your practice brief</h3><div class="formula" style="white-space:pre-wrap">${lessons[id]}</div><p>Practice locally and reflect on what you learned. Marking complete records progress only; it does not verify your skill or issue a certificate.</p><div class="modal-actions"><button class="btn ${S.completed.includes(id)?'':'primary'}" onclick="completeCourse(${id})" ${locked||S.completed.includes(id)?'disabled':''}>${S.completed.includes(id)?'Completed':'Mark as completed'} ${I('check')}</button></div>`)}
async function completeCourse(id){let c=courseData.find(c=>c.id===id);if(c.prereq&&!S.completed.includes(c.prereq))return;try{await save({completed:[...new Set([...S.completed,id])]});closeModal();render();toast('Milestone completed. Keep practicing, then reassess your skills.')}catch(e){toast(e.message)}}
function addProject(){modal('Add project evidence',`<form onsubmit="submitProject(event)"><div class="field"><label>Project title</label><input name="name" required maxlength="80" placeholder="e.g. Sales Analytics Dashboard"></div><div class="field"><label>What did you build?</label><textarea name="description" required maxlength="500" placeholder="Describe the problem, your contribution, and the outcome."></textarea></div><div class="field"><label>Primary skill</label><select name="skill">${Object.keys(S.skills).map(s=>`<option>${s}</option>`).join('')}</select></div><p>Evidence is labelled self-reported. Adding a project can influence the experience component of matching, but never increases your skill scores.</p><div class="modal-actions"><button class="btn primary">Add to portfolio ${I('plus')}</button></div></form>`)}
async function submitProject(e){e.preventDefault();let f=new FormData(e.target);try{await save({projects:[...S.projects,{name:f.get('name'),description:f.get('description'),skills:[f.get('skill')],status:'Self-reported'}]});closeModal();render();toast('Project added to your Digital Portfolio.')}catch(e){toast(e.message)}}
function download(name,text,type='text/plain'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportPortfolio(){download('Kaizen-Portfolio.txt',`KAIZEN CONNECT · DIGITAL PORTFOLIO\nDEMO / SYNTHETIC DATA\n\n${S.profile.name}\n${S.profile.degree} · ${S.profile.institution}\n${S.profile.bio}\n\nSKILLS\n${Object.entries(S.skills).map(([k,v])=>`${k}: ${v}%`).join('\n')}\n\nPROJECTS (self-reported)\n${S.projects.map(p=>`${p.name}\n${p.description}\nSkills: ${p.skills.join(', ')}`).join('\n\n')}\n\nVerification: not independently verified.`);toast('Portfolio exported.')}
function matchingInfo(){modal('Explainable by design',`<p>The Skill Intelligence Engine uses deterministic rules, not an AI ranking model.</p><div class="process-path">${['Eligibility','Skill coverage','Preferences','Weighted score','Explanation'].map(s=>pill(s,'gray')).join(I('arrow'))}</div><table><tbody>${[['Skill coverage','50%'],['Interest category','20%'],['Education eligibility','15%'],['Relevant projects','10%'],['Location preference','5%']].map(([k,v])=>`<tr><td>${k}</td><td><b>${v}</b></td></tr>`).join('')}</tbody></table><p>Students must meet the degree filter before appearing in recommendations. Each required skill is capped at 100% coverage. Interest earns 100 for an exact category match, otherwise 40. Each relevant project earns 50 points, up to 100. Remote or your preferred city earns 100 location points.</p><p>All opportunities and requirements in this workspace are synthetic. A matching score is not a probability of being hired.</p>`)}
function guide(){modal('From Skills to Opportunities',`<p>Kaizen Connect connects career guidance to practical skill development and industry opportunities.</p>${['Build a profile with your education and preferences.','Take a practice assessment to create a Skill Profile.','Choose a target role and see exactly which skills need work.','Follow curated learning tied to those gaps.','Explore internships with a transparent “why matched” explanation.','Apply, switch to the Industry Portal, and shortlist the candidate.','Open the Institution Portal to see aggregate progress.'].map((s,i)=>`<div class="activity-item"><span class="square peach">${i+1}</span><strong>${s}</strong></div>`).join('')}<p>Use the portal selector in the sidebar to explore the ecosystem. No real authentication, integrations, or AI services are enabled in this demo.</p>`)}
function demoInfo(){modal('Your demo workspace',notice('Synthetic data only. This is a shared demonstration, not a secure production service.')+`<p>Switch portals using the selector in the sidebar. Changes are persisted in the local SQLite database.</p><p><b>Implemented:</b> profile editing, assessment, deterministic skills and gaps, learning milestones, opportunities, consent-based application snapshots, recruiter status changes, portfolio export, and cohort analytics.</p><p><b>Future scope:</b> production authentication, enforced role-based permissions, document storage and verification, external integrations, and optional LLM explanations.</p>`)}
function notifications(){modal('Your latest updates',`<div class="activity-item"><div class="square green">${I('internship')}</div><div><strong>${ranked('Internship').length} internship matches are ready</strong><p>Based on your current skills and preferences.</p></div></div>${S.applications.map(a=>{let o=S.opportunities.find(o=>o.id===a.opportunityId);return `<div class="activity-item"><div class="square peach">${I('application')}</div><div><strong>${esc(o.title)}</strong><p>Your application is ${a.status.toLowerCase()}.</p></div></div>`}).join('')}<div class="modal-actions">${btn('View opportunities',"closeModal();go('Internships')",true)}</div>`)}
function industry(){if(page==='Company Profile')return heading('A company students can connect with','Your industry identity, expectations, and opportunities.')+`<div class="card full-card"><div class="company-logo purple" style="width:60px;height:60px">L</div><h2 class="mt">Lumina Labs</h2>${pill('Synthetic demo company','orange')}<p>We are a fictional analytics team helping growing businesses make better decisions with data. Our demo opportunities connect student skills with practical projects.</p><div class="two-col"><div><h3>Industry</h3><p>Data & Analytics · Pune · Hybrid</p></div><div><h3>Focus skills</h3><div class="tags">${['Python','SQL','Excel','Statistics','Power BI'].map(s=>`<span class="tag">${s}</span>`).join('')}</div></div></div></div>`;
if(page==='Opportunities')return heading('Good opportunities start with clear skills','Define requirements that students can understand and work toward.',btn('Post opportunity','postOpportunity()',true,'plus'))+`<div class="two-col">${S.opportunities.filter(o=>o.company==='Lumina Labs').map(o=>`<div class="card">${opRow(o)}<div class="card-foot">${S.applications.filter(a=>a.opportunityId===o.id).length} applications · Demo company posting</div></div>`).join('')}</div>`;
if(page==='Candidates')return heading('Potential, backed by a clear profile','Discover consenting applicants against your opportunity requirements.')+notice('This demo only exposes profiles after the student applies and consents. It does not enable unrestricted recruiter access to student records.')+recruiterTable();
if(page==='Applications')return heading('From application to possibility','Review profiles and move candidates through a traceable hiring process.')+recruiterTable();
if(page==='Analytics')return heading('Your hiring journey, in focus','Live application counts for your demo company.')+industryStats()+`<div class="card full-card"><h2>Application pipeline</h2>${pipeline()}<p>No predictive placement claims. These counts reflect actual actions in this demo workspace.</p></div>`;
return heading('Build your team around potential.','Find students with the skills you need — and the drive to keep growing.',btn('Post opportunity','postOpportunity()',true,'plus'))+`<div class="hero"><div><div class="eyebrow">INDUSTRY × ACADEMIA</div><h2>The right skills.<br>The right starting point.</h2><p>Set clear requirements. Discover potential. Support the next generation.</p>${btn('Review applicants',"go('Applications')",true)}</div><div class="hero-visual"><div class="orbit"></div><div class="hero-center">${I('mentorship')}</div><div class="floating one">${I('checkcircle')} Skills-first hiring</div><div class="floating three">${I('shield')} Explainable matching</div></div></div>`+industryStats()+`<div class="dashboard-columns"><div><div class="card">${head('Your active opportunities','Clear requirements create better connections.',link('View all','Opportunities'))}${S.opportunities.filter(o=>o.company==='Lumina Labs').slice(0,2).map(opRow).join('')}</div></div><div><div class="card full-card"><h2>A skill-driven hiring flow</h2>${['Post an opportunity','Define skills and eligibility','Review consenting candidates','Shortlist and interview','Select and support'].map((t,i)=>`<div class="activity-item"><div class="square ${i===2?'peach':'blue'}">${i+1}</div><strong>${t}</strong></div>`).join('')}</div></div></div>`}
function companyApps(){return S.applications.filter(a=>S.opportunities.find(o=>o.id===a.opportunityId)?.company==='Lumina Labs')}
function industryStats(){let apps=companyApps();return `<div class="stats">${stat('Active opportunities',S.opportunities.filter(o=>o.company==='Lumina Labs').length,'Internships and jobs','internship','blue')}${stat('Applications received',apps.length,'Consenting student profiles','application')}${stat('Shortlisted',apps.filter(a=>['Shortlisted','Interview'].includes(a.status)).length,'Candidates moving forward','mentorship','purple')}${stat('Selected',apps.filter(a=>a.status==='Selected').length,'Recorded demo outcomes','checkcircle','green')}</div>`}
const transitions={'Submitted':['Under Review','Rejected'],'Under Review':['Shortlisted','Rejected'],'Shortlisted':['Interview','Rejected'],'Interview':['Selected','Rejected'],'Selected':[],'Rejected':[],'Withdrawn':[]};
function recruiterTable(){let apps=companyApps();if(!apps.length)return empty('Your next candidate is on the way','Switch to the Student Portal and apply to a Lumina Labs opportunity to start the demo.');return `<div class="card"><div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Opportunity</th><th>Applied</th><th>Profile</th><th>Application status</th></tr></thead><tbody>${apps.map(a=>{let o=S.opportunities.find(o=>o.id===a.opportunityId);return `<tr><td><strong>${esc(a.snapshot.profile.name)}</strong><div class="small-text">${esc(a.snapshot.profile.degree)}</div></td><td>${esc(o.title)}</td><td>${a.date}</td><td><button class="text-link" onclick="candidateDetail(${a.id})">Review ${I('arrow')}</button></td><td><select class="status-select" aria-label="Application status for ${esc(a.snapshot.profile.name)}" onchange="changeStatus(${a.id},this.value)"><option>${a.status}</option>${(transitions[a.status]||[]).map(s=>`<option>${s}</option>`).join('')}</select></td></tr>`}).join('')}</tbody></table></div><div class="card-foot">${I('shield')} Review uses the consented snapshot saved at application time.</div></div>`}
function candidateDetail(id){let a=S.applications.find(a=>a.id===id),p=a.snapshot,o=S.opportunities.find(o=>o.id===a.opportunityId);modal('Candidate profile',`<h3 style="margin-top:0">${esc(p.profile.name)}</h3><p>${esc(p.profile.degree)} · ${esc(p.profile.institution)}<br>${esc(p.profile.bio)}</p>${pill('Consented application snapshot','green')}<h3>Skills against opportunity requirements</h3><table><thead><tr><th>Skill</th><th>Candidate</th><th>Required</th></tr></thead><tbody>${Object.entries(o.requirements).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${p.skills[k]||0}%</td><td>${v}%</td></tr>`).join('')}</tbody></table><h3>Projects · self-reported</h3>${p.projects.map(p=>`<p><strong>${esc(p.name)}</strong><br>${esc(p.description)}</p>`).join('')}<h3>Introduction</h3><p>${esc(a.note)||'No additional introduction.'}</p><div class="modal-actions">${(transitions[a.status]||[]).filter(s=>s!=='Rejected').map(s=>btn(s==='Under Review'?'Start review':s==='Shortlisted'?'Shortlist candidate':s==='Interview'?'Move to interview':'Select candidate',`changeStatus(${a.id},'${s}');closeModal()`,true)).join('')}</div>`)}
async function changeStatus(id,status){let a=S.applications.find(a=>a.id===id);if(status!=='Withdrawn'&&!(transitions[a.status]||[]).includes(status))return toast('Invalid application transition.');try{let date=new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});await save({applications:S.applications.map(a=>a.id===id?{...a,status,history:[...a.history,{status,date}]}:a),audit:[...S.audit,{action:`Application ${id}: ${status}`,at:new Date().toISOString(),actor:portal}]});render();toast(`Application updated to ${status.toLowerCase()}.`)}catch(e){toast(e.message)}}
function postOpportunity(){modal('Create a skill-first opportunity',`<form onsubmit="submitOpportunity(event)"><div class="form-grid"><div class="field wide"><label>Opportunity title</label><input name="title" required maxlength="90" placeholder="e.g. Data Science Intern"></div><div class="field"><label>Type</label><select name="type"><option>Internship</option><option>Job</option></select></div><div class="field"><label>Location</label><input name="location" required value="Pune" maxlength="60"></div><div class="field"><label>Work arrangement</label><select name="mode"><option>Hybrid</option><option>Remote</option><option>On-site</option></select></div><div class="field"><label>Stipend / salary</label><input name="stipend" required placeholder="₹15,000 / month" maxlength="60"></div><div class="field"><label>Duration</label><input name="duration" required value="3 months" maxlength="40"></div><div class="field"><label>Education eligibility</label><select name="education"><option value="all">B.Sc. Data Science, B.Tech, BCA</option><option>B.Tech</option><option>B.Sc. Data Science</option><option>BCA</option></select></div><div class="field wide"><label>Description</label><textarea name="description" required maxlength="700" placeholder="What will the student work on?"></textarea></div></div><h3>Required proficiency · 0–100</h3><p>Set a value above zero to require a skill. Zero excludes it.</p><div class="form-grid">${Object.keys(S.skills).filter(k=>!['Communication','Teamwork','Problem Solving'].includes(k)).map(k=>`<div class="field"><label>${k}</label><input name="skill-${k}" type="number" min="0" max="100" value="${['Python','SQL'].includes(k)?60:0}" required></div>`).join('')}</div><p class="small-text">Posts under Lumina Labs · Data & Analytics. All posted opportunities are demo data.</p><div class="modal-actions"><button class="btn primary" type="submit">Publish opportunity ${I('plus')}</button></div></form>`)}
async function submitOpportunity(e){e.preventDefault();let f=new FormData(e.target),req={};for(let [k,v] of f){if(k.startsWith('skill-')&&Number(v)>0)req[k.slice(6)]=Number(v)}if(!Object.keys(req).length)return toast('Add at least one required skill.');let o={id:Date.now(),title:f.get('title'),type:f.get('type'),location:f.get('mode')==='Remote'?'Remote':f.get('location'),mode:f.get('mode'),stipend:f.get('stipend'),duration:f.get('duration'),description:f.get('description'),education:f.get('education')==='all'?['B.Sc. Data Science','B.Tech','BCA']:[f.get('education')],requirements:req,company:'Lumina Labs',initials:'L',color:'purple',category:'Data & Analytics',posted:'Just now'};try{await save({opportunities:[...S.opportunities,o]});closeModal();go('Opportunities');toast('Opportunity published. Eligible students can now discover it.')}catch(e){toast(e.message)}}
const mockStudents=[{name:'Ananya Joshi',degree:'B.Sc. Data Science',skills:{Python:78,SQL:62,Excel:80,Statistics:70,'Power BI':58,GIS:15}},{name:'Rohan Patil',degree:'B.Sc. Data Science',skills:{Python:55,SQL:40,Excel:71,Statistics:55,'Power BI':30,GIS:20}},{name:'Ishita Kulkarni',degree:'B.Sc. Data Science',skills:{Python:80,SQL:68,Excel:90,Statistics:75,'Power BI':60,GIS:30}},{name:'Kabir Shah',degree:'B.Sc. Data Science',skills:{Python:60,SQL:35,Excel:65,Statistics:48,'Power BI':25,GIS:10}},{name:'Diya Nair',degree:'B.Sc. Data Science',skills:{Python:70,SQL:55,Excel:76,Statistics:64,'Power BI':50,GIS:25}}];
function cohort(){return [{name:S.profile.name,degree:S.profile.degree,skills:S.skills},...mockStudents]}
function cohortReady(s){return Math.round(Object.entries(roles['Data Analyst']).reduce((a,[k,v])=>a+Math.min((s.skills[k]||0)/v,1),0)/5*100)}
function cohortAvg(){return Math.round(cohort().reduce((a,s)=>a+cohortReady(s),0)/cohort().length)}
function institutionStats(){return `<div class="stats">${stat('Students in cohort','06','1 interactive + 5 synthetic profiles','mentorship','blue')}${stat('Average readiness',cohortAvg()+'<span>%</span>','Data Analyst role coverage','target','purple')}${stat('Internship participation',S.applications.some(a=>a.status==='Selected'&&S.opportunities.find(o=>o.id===a.opportunityId).type==='Internship')?'1 / 6':'0 / 6','Students selected for internships','internship')}${stat('Applications',S.applications.length,'Tracked from the interactive profile','application','green')}</div>`}
function distribution(){return `<div class="metric-bars">${Object.keys(roles['Data Analyst']).map(k=>{let n=Math.round(cohort().reduce((a,s)=>a+(s.skills[k]||0),0)/cohort().length);return `<div class="metric-bar"><b>${n}%</b><i style="height:${n*1.5}px"></i><span>${k}</span></div>`}).join('')}</div><div class="cohort-note">Demo cohort · mean proficiency per skill · n = 6</div>`}
function trainingTable(){return `<div class="table-wrap"><table><thead><tr><th>Skill</th><th>Role benchmark</th><th>Students below benchmark</th><th>Training need</th></tr></thead><tbody>${Object.entries(roles['Data Analyst']).map(([k,v])=>{let n=cohort().filter(s=>(s.skills[k]||0)<v).length;return `<tr><td><strong>${k}</strong></td><td>${v}%</td><td>${n} of 6</td><td>${pill(n>=4?'High':n>=2?'Medium':'Low',n>=4?'red':n>=2?'orange':'green')}</td></tr>`}).join('')}</tbody></table></div>`}
function pipeline(){let apps=portal==='Industry'?companyApps():S.applications;return `<div class="metric-bars">${['Submitted','Under Review','Shortlisted','Interview','Selected','Rejected'].map(s=>{let n=apps.filter(a=>a.status===s).length;return `<div class="metric-bar"><b>${n}</b><i style="height:${Math.max(3,n/Math.max(1,apps.length)*140)}px;background:${s==='Selected'?'#7aac97':'#f0a58e'}"></i><span style="font-size:8px;text-align:center">${s}</span></div>`}).join('')}</div>`}
function institution(){if(page==='Students')return heading('Understand your student community','A small synthetic cohort to demonstrate institutional visibility.')+`<div class="card"><table><thead><tr><th>Student</th><th>Degree</th><th>Data Analyst readiness</th><th>Record type</th></tr></thead><tbody>${cohort().map((s,i)=>`<tr><td><strong>${esc(s.name)}</strong></td><td>${esc(s.degree)}</td><td>${cohortReady(s)}%</td><td>${pill(i===0?'Interactive demo':'Synthetic record',i===0?'orange':'gray')}</td></tr>`).join('')}</tbody></table></div>`+notice('Institution views are scoped conceptually to this demo institution. Production tenant-level authorization and academic record access controls are not implemented.');
if(page==='Skill Analytics')return heading('See the gaps. Support the growth.','Skill trends connected to actual role requirements.',btn('Export report','exportReport()',false,'download'))+institutionStats()+`<div class="two-col"><div class="card full-card"><h2>Skill distribution</h2>${distribution()}</div><div class="card full-card"><h2>Training priorities</h2><p>${cohort().filter(s=>s.skills.SQL<70).length} of 6 students need additional SQL training for the Data Analyst benchmark.</p><p>${cohort().filter(s=>s.skills['Power BI']<65).length} of 6 students need Power BI development. A targeted workshop followed by a dashboard project is a practical intervention.</p>${pill('Derived from synthetic cohort','orange')}</div></div><div class="card">${trainingTable()}</div>`;
if(page==='Placement Progress')return heading('Progress beyond the classroom','Track applications and outcomes, without predictive claims.')+institutionStats()+`<div class="card full-card"><h2>Application stages</h2>${pipeline()}<p>Selection records are demo decisions. A selected internship is not a completed internship; a selected job is not a verified joining.</p></div>`;
if(page==='Industry Demand'){let counts={};S.opportunities.forEach(o=>Object.keys(o.requirements).forEach(k=>counts[k]=(counts[k]||0)+1));return heading('Connect learning with industry needs','Demand signals from opportunities published in this workspace.')+notice('This is not a labour-market report. Counts come only from synthetic opportunities in the demo database.')+`<div class="card"><table><thead><tr><th>Skill</th><th>Opportunities requiring skill</th><th>Share of postings</th></tr></thead><tbody>${Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([k,n])=>`<tr><td><strong>${esc(k)}</strong></td><td>${n} of ${S.opportunities.length}</td><td>${Math.round(n/S.opportunities.length*100)}%</td></tr>`).join('')}</tbody></table></div>`}
return heading('A clearer view. A stronger student community.','Connect student readiness with the support that makes a difference.',btn('Export report','exportReport()',false,'download'))+notice('Demo analytics · 6 synthetic students, including the interactive Aarav profile. Skill averages update with assessments. Applications and outcomes use live demo actions.')+institutionStats()+`<div class="dashboard-columns"><div><div class="card full-card"><div style="display:flex;justify-content:space-between"><h2>Student skill distribution</h2>${link('Explore analytics','Skill Analytics')}</div>${distribution()}</div><div class="card">${head('Where support can make a difference','Data Analyst role · curated demo requirements')}<div class="mt">${trainingTable()}</div></div></div><div><div class="card full-card"><h2>Turn an insight into action</h2><div class="square peach">${I('learning')}</div><h3>Make SQL a training priority.</h3><p>${cohort().filter(s=>s.skills.SQL<70).length} of 6 students are below the SQL benchmark. A focused workshop and hands-on project can help bridge the gap.</p>${link('Review industry demand','Industry Demand')}</div><div class="card full-card"><h2>Placement readiness</h2><div class="readiness">${ring(cohortAvg())}<p>Average coverage of Data Analyst requirements across the synthetic cohort.</p></div>${link('View placement progress','Placement Progress')}</div></div></div>`}
function exportReport(){let lines=['Demo data - Kaizen Connect - synthetic cohort','Student,Degree,Data Analyst Readiness,Python,SQL,Excel,Statistics,Power BI',...cohort().map(s=>[s.name,s.degree,cohortReady(s),...Object.keys(roles['Data Analyst']).map(k=>s.skills[k]||0)].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(','))];download('Kaizen-Demo-Readiness.csv',lines.join('\n'),'text/csv');toast('Synthetic cohort report exported.')}
function academician(){if(page==='Mentorship')return heading('Help a student take their next step','Lightweight faculty mentorship workspace.')+(S.mentorshipRequests.length?`<div class="card full-card"><h2>Guidance requests</h2>${S.mentorshipRequests.map(id=>`<div class="activity-item"><div class="avatar">AS</div><div><strong>${esc(S.profile.name)}</strong><p>Requested ${id===1?'Dr. Meera Rao':'Prof. Rohan Desai'} · Skill and career guidance</p></div>${pill('Request recorded','orange')}</div>`).join('')}<p>Request tracking only. Scheduling and messaging are not part of this MVP.</p></div>`:empty('No guidance requests yet','Students can request faculty guidance from their Mentorship page.'));
if(page==='Collaboration')return heading('Bring academia and industry closer','A future-ready collaboration layer, kept intentionally lightweight.')+notice('Future scope · The following collaboration pathways are a product roadmap, not active programmes.')+`<div class="three-col">${['Faculty Development Programmes','Industrial Training','Live Research Projects','Guest Lectures & Workshops','Consultancy','Innovation Challenges'].map(n=>`<div class="card full-card"><div class="square purple">${I('building')}</div><h2 class="mt">${n}</h2><p>Extend the skill ecosystem through institution-approved, industry-supported collaboration.</p>${pill('Future extension','gray')}</div>`).join('')}</div>`;
return heading('Guidance that connects learning to life.','Support students, collaborate with industry, and build practical pathways.')+notice('Academician Portal · Lightweight MVP. Guidance request visibility is implemented; programme management, research, FDPs, and consultancy remain future scope.')+`<div class="stats">${stat('Guidance requests',S.mentorshipRequests.length,'Recorded in this demo','mentorship','purple')}${stat('Student cohort','06','Synthetic institution records','learning','blue')}${stat('Collaboration pathways','06','Future-scope extensions','building')}${stat('Industry opportunities',S.opportunities.length,'Synthetic postings','internship','green')}</div><div class="two-col"><div class="card full-card"><h2>Be the next useful conversation.</h2><p>Help students interpret skill gaps, strengthen a project, and make informed choices about opportunities.</p>${btn('View guidance requests',"go('Mentorship')",true)}</div><div class="card full-card"><h2>Build bridges beyond the classroom.</h2><p>Explore the future roadmap for industrial training, faculty development, research, and innovation.</p>${btn('Explore collaboration',"go('Collaboration')")}</div></div>`}
async function init(){try{if(standalone){const saved=localStorage.getItem(standaloneStorageKey);S=saved?JSON.parse(saved):JSON.parse(JSON.stringify(defaultState))}else{let r=await fetch('/api/state');if(!r.ok)throw Error('Unable to load workspace');S=await r.json()}selectedRole=S.profile.preferredRole in roles?S.profile.preferredRole:'Data Analyst';render()}catch(e){document.getElementById('app').innerHTML=`<div class="empty"><h3>We couldn’t load your workspace.</h3><p>${esc(e.message||'Check the server connection and try again.')}</p><button class="btn primary" onclick="init()">Retry</button></div>`}}
init();

async function setTargetRole(role,navigate=false){if(!(role in roles))return;try{await save({profile:{...S.profile,preferredRole:role}});selectedRole=role;if(navigate)go('Skill Gaps');else render()}catch(e){toast(e.message)}}
function nextCourses(){return courseData.filter(c=>c.skill in roles[selectedRole]&&gap(c.skill,roles[selectedRole][c.skill])>0&&!S.completed.includes(c.id)&&(!c.prereq||S.completed.includes(c.prereq))).sort((a,b)=>gap(b.skill,roles[selectedRole][b.skill])-gap(a.skill,roles[selectedRole][a.skill])).slice(0,2)}
